import 'package:flutter/services.dart';

/// One choice in Settings → App icon. [alias] is the `<activity-alias>` in
/// AndroidManifest.xml that carries this icon; `MainActivity` is the official
/// logo and must keep that name (old home-screen shortcuts point at it).
class AppIconOption {
  final String id;
  final String label;
  final String alias;

  const AppIconOption(this.id, this.label, this.alias);

  /// Small square preview, generated by `tool/generate_app_icons.py`.
  String get previewAsset => 'assets/app_icons/$id.png';

  bool get isClassic => id == kClassicIcon;
}

const String kClassicIcon = 'classic';

/// Free for everyone. Order is the order shown in Settings.
const List<AppIconOption> kAppIcons = [
  AppIconOption(kClassicIcon, 'Classic', 'MainActivity'),
  AppIconOption('keypad', 'Keypad', 'IconKeypad'),
  AppIconOption('amber', 'Plus', 'IconAmber'),
  AppIconOption('operators', 'Operators', 'IconOperators'),
  AppIconOption('plusminus', 'Plus-Minus', 'IconPlusminus'),
  AppIconOption('percent', 'Percent', 'IconPercent'),
  AppIconOption('root', 'Root', 'IconRoot'),
  AppIconOption('ruler', 'Ruler', 'IconRuler'),
];

AppIconOption appIconOf(String id) =>
    kAppIcons.firstWhere((o) => o.id == id, orElse: () => kAppIcons.first);

/// Switches the launcher icon through the `popcalc/app_icon` channel in
/// PopCalcActivity.kt, which holds it until the app is left (no restart).
/// Fire-and-forget: where there is no native side (tests, other platforms)
/// it quietly does nothing.
class AppIconService {
  static const _channel = MethodChannel('popcalc/app_icon');

  static Future<bool> apply(String id) async {
    try {
      return await _channel.invokeMethod<bool>('set', {
            'alias': appIconOf(id).alias,
          }) ??
          false;
    } catch (_) {
      return false;
    }
  }
}
